"""Second question types for Numerical Methods (NM)."""
from opl_dsl import Q

FILE, FRAMEWORK = "nm-second-types", "numerical-methods"
ADD = [
    ("NM-1.1.A", Q("nm-bisection-error-bound", "nm.roots", "Bisection starts on [{{a}}, {{b}}]. After {{n}} halvings, what is the largest possible error of the midpoint of the last bracket?",
        given={"a": {"pick": [0, 1]}, "b": {"pick": [2, 3, 4]}, "n": {"int": [3, 10]}}, value="(b - a)/2^(n + 1)", tex="|e|",
        verify="Rational(b - a, 2**n)/2", explain="Each halving shrinks the bracket by 2; the midpoint is at most half a bracket from the root")),
    ("NM-1.1.B", Q("nm-newton-reciprocal", "nm.roots", "Newton's method on f(x) = 1/x − {{a}} computes 1/{{a}} without division. From $x_0$ = {{x0}}, what is $x_1$?",
        given={"a": {"pick": [3, 7, 9]}, "x0": {"pick": [0.1, 0.2]}}, require=["x0 < 2/a"], value="x0*(2 - a*x0)", tex="x_1",
        verify="nsimplify(x0) - (1/Symbol('t') - a).subs(Symbol('t'), nsimplify(x0))/diff(1/Symbol('t') - a, Symbol('t')).subs(Symbol('t'), nsimplify(x0))",
        explain="x − f/f′ simplifies to x(2 − ax): only multiplications, which is how early hardware divided. It converges for 0 < x₀ < 2/a")),
    ("NM-1.1.C", Q("nm-false-position", "nm.roots", "Apply one step of false position to f(x) = x² − {{c}} on the bracket [{{a}}, {{b}}]. Where does the chord cross zero?",
        given={"c": {"pick": [2, 3, 5, 7]}, "a": {"pick": [1]}, "b": {"pick": [3]}}, value="b - (b^2 - c)*(b - a)/((b^2 - c) - (a^2 - c))", tex="x_r",
        verify="solve(Eq((a**2 - c) + ((b**2 - c) - (a**2 - c))/(b - a)*(x - a), 0), x)[0]",
        explain="Like the secant step, but it keeps a bracket with a sign change, so it cannot diverge; one end can stall, though")),
    ("NM-1.1.D", Q("nm-fixed-point-iterations", "nm.roots", "Fixed-point iteration converges linearly with |g′(root)| = {{L}}. About how many iterations reduce the error by a factor of 10^{{k}}?",
        given={"L": {"pick": [0.1, 0.3, 0.5, 0.9]}, "k": {"pick": [3, 6]}}, value="k*log(10)/(-log(L))", tex="n",
        verify="log(Rational(1, 10**k))/log(nsimplify(L))", explain="Each step multiplies the error by about |g′|: L = 0.9 needs over 130 steps for six digits, which is why Newton is preferred")),
    ("NM-2.1.A", Q("nm-jacobi-spectral", "nm.linear-iter", "For A = [[{{a}}, {{b}}], [{{c}}, {{d}}]], what is the spectral radius of the Jacobi iteration matrix?",
        given={"a": {"pick": [4, 5, 10]}, "b": {"pick": [1, 2, -3]}, "c": {"pick": [1, 2, 3]}, "d": {"pick": [3, 6, 8]}}, value="sqrt(abs(b*c/(a*d)))", tex="\\rho(T_J)",
        verify="Max(*[Abs(v) for v in (-Matrix([[a, 0], [0, d]]).inv()*Matrix([[0, b], [c, 0]])).eigenvals()])",
        explain="Jacobi converges for every start exactly when ρ < 1; the error shrinks by about ρ each sweep")),
    ("NM-2.1.B", Q("nm-gauss-seidel-spectral", "nm.linear-iter", "For A = [[{{a}}, {{b}}], [{{c}}, {{d}}]], what is the spectral radius of the Gauss–Seidel iteration matrix?",
        given={"a": {"pick": [4, 5, 10]}, "b": {"pick": [1, 2, -3]}, "c": {"pick": [1, 2, 3]}, "d": {"pick": [3, 6, 8]}}, value="abs(b*c/(a*d))", tex="\\rho(T_{GS})",
        verify="Max(*[Abs(v) for v in (-Matrix([[a, 0], [c, d]]).inv()*Matrix([[0, b], [0, 0]])).eigenvals()])",
        explain="For 2×2 (and consistently ordered) systems ρ_GS = ρ_J²: Gauss–Seidel needs about half as many sweeps")),
    ("NM-2.1.C", Q("nm-dominance-threshold", "nm.linear-iter", "What is the smallest integer k that makes [[k, {{p}}, {{q}}], [{{r}}, k, {{s}}], [{{t}}, {{u}}, k]] strictly diagonally dominant by rows?",
        given={"p": {"int": [-3, 3]}, "q": {"int": [1, 4]}, "r": {"int": [-2, 3]}, "s": {"int": [1, 5]}, "t": {"int": [1, 3]}, "u": {"int": [-4, 2]}},
        value="max(abs(p) + abs(q), abs(r) + abs(s), abs(t) + abs(u)) + 1", tex="k", final=True,
        verify="Max(Abs(p) + Abs(q), Abs(r) + Abs(s), Abs(t) + Abs(u)) + 1", explain="Each diagonal must beat the sum of its row's other magnitudes; the worst row sets k")),
    ("NM-3.1.A", Q("nm-divided-difference", "nm.interp", "Data: f({{x0}}) = {{f0}}, f({{x1}}) = {{f1}}, f({{x2}}) = {{f2}}. What is the second divided difference f[x₀, x₁, x₂]?",
        given={"x0": {"pick": [0, 1]}, "x1": {"pick": [2, 3]}, "x2": {"pick": [4, 5]}, "f0": {"int": [-3, 5]}, "f1": {"int": [0, 9]}, "f2": {"int": [-2, 12]}},
        value="((f2 - f1)/(x2 - x1) - (f1 - f0)/(x1 - x0))/(x2 - x0)", tex="f[x_0,x_1,x_2]",
        verify="Matrix([[x0**2, x0, 1], [x1**2, x1, 1], [x2**2, x2, 1]]).solve(Matrix([f0, f1, f2]))[0]",
        explain="The second divided difference is the leading coefficient of the interpolating quadratic, which the Vandermonde solve confirms")),
    ("NM-3.2.A", Q("nm-simpson-error", "nm.quadrature", "Simpson's rule (one panel) is applied to $\\int_0^{{b}} x^4\\,dx$. What is its error (Simpson minus exact)?",
        given={"b": {"pick": [1, 2, 3]}}, value="b^5/120", tex="E", verify="Rational(b, 6)*(0 + 4*Rational(b, 2)**4 + b**4) - integrate(Symbol('q')**4, (Symbol('q'), 0, b))",
        explain="Simpson is exact for cubics, so a quartic shows its leading error, (b − a)⁵f⁗/2880 = b⁵·24/2880")),
    ("NM-3.2.B", Q("nm-trapezoid-panels", "nm.quadrature", "The composite trapezoid rule on [0, {{L}}] has error (b − a)³|f″|/(12n²). With |f″| = {{f2}} everywhere, how many panels keep the error below {{tol}}?",
        given={"L": {"pick": [1, 2]}, "f2": {"pick": [2, 6, 10]}, "tol": {"pick": [0.01, 0.001]}}, value="ceil(sqrt(L^3*f2/(12*tol)))", tex="n", final=True,
        verify="ceiling(Max(*solve(Eq(L**3*f2/(12*x**2), nsimplify(tol)), x)))", explain="Error ∝ 1/n²: ten times tighter needs about three times the panels")),
    ("NM-3.2.C", Q("nm-richardson-cubic", "nm.quadrature", "For $\\int_0^{{b}} ({{c3}}x^3 + {{c1}}x)\\,dx$, take the trapezoid rule with one and two panels and apply Richardson extrapolation (4T₂ − T₁)/3. What value results?",
        given={"b": {"pick": [1, 2]}, "c3": {"int": [1, 4]}, "c1": {"int": [-3, 3]}}, value="c3*b^4/4 + c1*b^2/2", tex="I_R",
        verify="integrate(c3*Symbol('q')**3 + c1*Symbol('q'), (Symbol('q'), 0, b))",
        explain="One Richardson step on the trapezoid rule is Simpson's rule, exact for cubics; the value equals the integral")),
    ("NM-3.2.D", Q("nm-gauss-three-point", "nm.quadrature", "Three-point Gauss–Legendre uses nodes 0, ±√(3/5) with weights 8/9, 5/9. Apply it to $\\int_{-1}^{1} ({{a}}x^4 + {{c}})\\,dx$.",
        given={"a": {"int": [1, 5]}, "c": {"int": [0, 3]}}, value="2*a/5 + 2*c", tex="I_G",
        verify="integrate(a*Symbol('q')**4 + c, (Symbol('q'), -1, 1))", explain="n Gauss points integrate polynomials up to degree 2n − 1 exactly: three points handle a quintic")),
    ("NM-4.1.A", Q("nm-midpoint-step", "nm.ode", "Take one midpoint (RK2) step of size h = {{h}} for y′ = t + y from t₀ = {{t0}}, y₀ = {{y0}}.",
        given={"h": {"pick": [0.1, 0.2, 0.5]}, "t0": {"pick": [0, 1]}, "y0": {"pick": [1, 2]}}, value="y0 + h*((t0 + h/2) + (y0 + h/2*(t0 + y0)))", tex="y_1",
        verify="nsimplify(y0) + nsimplify(h)*(t0 + y0) + nsimplify(h)**2/2*(1 + t0 + y0)",
        explain="Second-order methods match the Taylor series through h²: for this linear ODE the midpoint step equals that truncated series exactly")),
    ("NM-4.1.B", Q("nm-rk4-stability", "nm.ode", "Classical RK4 on y′ = λy has amplification R(z) = 1 + z + z²/2 + z³/6 + z⁴/24 with z = λh. For λh = {{z}}, is the step stable (|R| ≤ 1)?",
        given={"z": {"pick": [-0.5, -1.5, -2.5, -2.7, -2.9, -3.2]}}, choice=["Stable", "Unstable"], correct="abs(1 + z + z^2/2 + z^3/6 + z^4/24) <= 1 ? 0 : 1",
        verify="0 if Abs(series(exp(Symbol('zz')), Symbol('zz'), 0, 5).removeO().subs(Symbol('zz'), nsimplify(z))) <= 1 else 1",
        explain="R(z) is the Taylor polynomial of e^z; on the real axis RK4 stays stable to about λh = −2.785")),
    ("NM-4.1.C", Q("nm-backward-euler", "nm.ode", "Take one backward (implicit) Euler step for y′ = {{lam}}y with h = {{h}} from y₀ = {{y0}}.",
        given={"lam": {"pick": [-5, -20, -100]}, "h": {"pick": [0.1, 0.5]}, "y0": {"pick": [1, 2]}}, value="y0/(1 - lam*h)", tex="y_1",
        verify="solve(Eq(x, y0 + nsimplify(h)*lam*x), x)[0]", explain="Implicit Euler damps any negative λ for any h: stable where explicit Euler (needing h < 2/|λ|) would blow up")),
    ("NM-4.1.D", Q("nm-stiffness-ratio", "nm.ode", "What is the stiffness ratio (largest over smallest |eigenvalue|) of y′ = Ay with A = [[{{a}}, {{b}}], [0, {{d}}]]?",
        given={"a": {"pick": [-1, -2]}, "b": {"pick": [1, 5]}, "d": {"pick": [-50, -200, -1000]}}, value="max(abs(a), abs(d))/min(abs(a), abs(d))", tex="S",
        verify="Max(*[Abs(v) for v in Matrix([[a, b], [0, d]]).eigenvals()])/Min(*[Abs(v) for v in Matrix([[a, b], [0, d]]).eigenvals()])",
        explain="An explicit method must resolve the fastest mode for stability while the slowest sets how long you integrate: a ratio in the hundreds calls for an implicit method")),
    ("NM-5.1.A", Q("nm-forward-difference-error", "nm.diff", "Estimate f′({{x0}}) for f(x) = x³ with a forward difference, step h = {{h}}. What is the error of the estimate (estimate minus exact)?",
        given={"x0": {"pick": [1, 2]}, "h": {"pick": [0.1, 0.01]}}, value="3*x0*h + h^2", tex="E",
        verify="((nsimplify(x0) + nsimplify(h))**3 - nsimplify(x0)**3)/nsimplify(h) - 3*nsimplify(x0)**2",
        explain="Forward differences are first order: the error ≈ (h/2)f″ falls only tenfold when h does; central differences fall a hundredfold")),
]
